
class DamageInstanceBlock{
    constructor(attacker,receiver,dmgValue,originDmgMult,isComAtk,orgTact,baseDmgType,statusDmgType){
        //来自谁
        this.id = `${ Date.now()}${Math.random().toString(36).substring(2, 8)}` ;
        this.dmgCreateTurn = attacker.driver.turn;
        this.attacker = attacker;
        this.receiver = receiver
        this.dmgValue = dmgValue;
        this.originDmgMult = originDmgMult;

        this.isComAtk = isComAtk;
        this.orgTact = orgTact;
        this.baseDmgType = baseDmgType;
        this.statusDmgType = statusDmgType
        
    }
    
}

export default DamageInstanceBlock;